// Diddy Kong Racing Recompiled: registers the recompiled game with N64ModernRuntime and hands it to
// the shared frontend (frontend/). What the game needs beyond a correct symbol file, and why, is in
// docs/game-fixes.md; how the pieces fit is in docs/architecture.md.

#include <cstdio>
#include <cstring>

#include "recomp.h"
#include "librecomp/addresses.hpp"
#include "librecomp/game.hpp"
#include "librecomp/overlays.hpp"
#include "librecomp/rsp.hpp"
#include "ultramodern/ultramodern.hpp"
#include "frontend/frontend.hpp"

#include "recomp_overlays.inl" // generated by N64Recomp: the section table

extern "C" void recomp_entrypoint(uint8_t* rdram, recomp_context* ctx);
extern RspUcodeFunc aspMain; // the game's audio microcode, recompiled by RSPRecomp (rsp/aspMain.toml)

// XXH3_64 of the USA v1.1 ROM (SHA1 6d96743d46f8c0cd0edb0ec5600b003c89b93755).
constexpr uint64_t kRomHash = 0xB55D4348B9AB07F5ULL;

// Graphics tasks never get here: ultramodern sends them to RT64. Audio runs the recompiled aspMain,
// except for the empty command lists DKR sends now and then (alAudioFrame with nothing to play):
// aspMain starts on the first command without checking the length, so it would run whatever the
// last task left in DMEM. An empty list makes no sound, so it's just completed.
static RspExitReason no_ucode(uint8_t*, uint32_t) { return RspExitReason::Broke; }
static RspUcodeFunc* get_rsp_microcode(const OSTask* task) {
    return task->t.type == M_AUDTASK && task->t.data_size != 0 ? aspMain : no_ucode;
}

// A KSEG1 (uncached) address as the recompiled code reaches it: 512 MB past RDRAM's base.
static uint32_t& kseg1(uint8_t* rdram, uint32_t addr) { return *(uint32_t*)(rdram + (addr - 0x80000000u)); }

static void on_init(uint8_t* rdram, recomp_context*) {
    fe::set_rdram(rdram);
    // DKR's anti-piracy checks read hardware the recomp doesn't have, and quietly break the game
    // when the value is wrong (upside-down screen, a permanently pressed Start, uncollectable golden
    // balloons, ...). Give each read what a real console returns. docs/game-fixes.md lists them.
    kseg1(rdram, 0xA4000000) = 0xFFFFFFFF; // SP DMEM[0]           drm_validate_dmem
    kseg1(rdram, 0xA4001000) = 6103;       // SP IMEM[0]: CIC id   drm_validate_imem
    kseg1(rdram, 0xA0000200) = 0xAC290000; // low RDRAM            render_scene (mirrored tracks)
    kseg1(rdram, 0xA0000284) = 0x240B17D7; // low RDRAM            golden balloons
    // Cart ROM read directly (0xB0000574: race finish, 0xB0000578: upside-down screen): mirror the
    // ROM's first 4 KB there, as the cartridge bus would answer.
    recomp::do_rom_read(rdram, (gpr)(int32_t)0xB0000000u, recomp::rom_base, 0x1000);
    *(int32_t*)(rdram + 0x310) = 6103;     // osCicId (IPL3 sets it; the runtime doesn't)
}

static std::string thread_name(const OSThread* t) { return "DKR thread " + std::to_string(t->id); }

int main(int argc, char** argv) {
    recomp::overlays::overlay_section_table_data_t sections{ section_table, num_sections, num_sections };
    recomp::overlays::overlays_by_index_t overlays{ overlay_sections_by_index,
        sizeof(overlay_sections_by_index) / sizeof(overlay_sections_by_index[0]) };
    recomp::overlays::register_overlays(sections, overlays);

    recomp::GameEntry game{};
    game.rom_hash = kRomHash;
    game.internal_name = "Diddy Kong Racing";
    game.display_name = "Diddy Kong Racing";
    game.game_id = u8"dkr.us";
    game.mod_game_id = "dkr";
    game.save_type = recomp::SaveType::Eep4k;
    game.is_enabled = true;
    game.entrypoint_address = (gpr)(int32_t)0x80000400u;
    game.entrypoint = recomp_entrypoint;
    game.on_init_callback = on_init;
    if (!recomp::register_game(game)) {
        fprintf(stderr, "[dkr] failed to register the game\n");
        return 1;
    }

    recomp::Configuration cfg{};
    cfg.project_version = { 0, 2, 0, "-alpha" };
    cfg.rsp_callbacks.get_rsp_microcode = get_rsp_microcode;
    cfg.threads_callbacks.get_game_thread_name = thread_name;
    // DKR frees and reloads assets right after submitting a frame, and rebuilds vertices and
    // matrices once the RSP reports done; RT64 has to have read the display list by then
    // (docs/game-fixes.md).
    cfg.synchronous_rsp_tasks = true;

    fe::GameInfo info;
    info.title = "Diddy Kong Racing";
    info.game_id = u8"dkr.us";
    info.short_name = "dkr";
    info.rom_names = { "baserom.us.z64", "Diddy Kong Racing (U) [!].z64", "dkr.z64" };
    info.players = 4;
    info.env_prefix = "DKR_";
    printf("Diddy Kong Racing Recompiled %s\n", DKR_VERSION);
    return fe::run(info, cfg, argc, argv);
}
